#pragma once
#include "PluginProcessor.h"
struct TuningPanel:juce::Component{
 SynthMavenProcessor&p;int target;juce::ToggleButton master{"MASTER TUNING / ALL 8 LAYERS"},bypass{"BYPASS TUNING"},scala{"USE SCALA"};juce::ComboBox root,presets;juce::Slider reference;juce::Label title,info,help,referenceLabel;juce::TextButton load{"LOAD .SCL"},reset{"RESET"},store{"STORE"};std::array<juce::TextButton,12>keys;std::array<juce::Slider,12>cents;std::array<juce::TextButton,5>memories;bool storing=false;std::unique_ptr<juce::FileChooser>chooser;
 std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>>sliders;std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment>>buttons;
 TuningPanel(SynthMavenProcessor&proc):p(proc),target(p.parameters.getRawParameterValue("masterTuning")->load()>=.5f?8:p.selectedLayer.load()){
 using namespace juce;for(Component*c:std::initializer_list<Component*>{&master,&bypass,&scala,&root,&presets,&reference,&title,&info,&help,&referenceLabel,&load,&reset,&store})addAndMakeVisible(c);
 buttons.push_back(std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.parameters,"masterTuning",master));buttons.push_back(std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.parameters,p.tuningId(target,"bypass"),bypass));buttons.push_back(std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.parameters,p.tuningId(target,"scala"),scala));
 title.setText(target==8?"MASTER SCALE / overrides every layer":"LAYER "+String(target+1)+" / independent scale",dontSendNotification);title.setFont(Font(15,Font::bold));
 const StringArray names{"C","C#","D","D#","E","F","F#","G","G#","A","A#","B"};for(int n=0;n<12;n++){root.addItem("ROOT "+names[n],n+1);auto&key=keys[(size_t)n];addAndMakeVisible(key);key.setButtonText(names[n]);key.onClick=[this,n]{auto*param=p.parameters.getParameter(p.tuningId(target,"note"+String(n)));param->setValueNotifyingHost(std::abs(param->getValue()-.375f)<.005f?.5f:.375f);};auto&s=cents[(size_t)n];addAndMakeVisible(s);s.setRange(0,1);s.setSliderStyle(Slider::LinearVertical);s.setTextBoxStyle(Slider::TextBoxBelow,false,58,22);s.setDoubleClickReturnValue(true,.5);sliders.push_back(std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.parameters,p.tuningId(target,"note"+String(n)),s));s.textFromValueFunction=[](double v){return String((v-.5)*400,1)+" ct";};s.valueFromTextFunction=[](const String&v){return .5+v.getDoubleValue()/400;};s.updateText();s.setTooltip("Offset relative to root; click note for -50 cents, double-click slider to reset");}
 root.setSelectedId(1+roundToInt(p.parameters.getRawParameterValue(p.tuningId(target,"root"))->load()*11),dontSendNotification);root.onChange=[this]{p.parameters.getParameter(p.tuningId(target,"root"))->setValueNotifyingHost(root.getSelectedItemIndex()/11.f);};
 for(auto name:{"Equal / Custom","Rast / E and B half-flat","Bayati / D half-flat","Sikah starting point","Arabic quarter-tone starting point","Just intonation"})presets.addItem(name,presets.getNumItems()+1);presets.setTextWhenNothingSelected("TUNING STARTING POINT");presets.onChange=[this]{p.tuningPreset(target,presets.getSelectedId()-1);};
 reference.setRange(0,1);reference.setSliderStyle(Slider::LinearHorizontal);reference.setTextBoxStyle(Slider::TextBoxRight,false,90,24);sliders.push_back(std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.parameters,p.tuningId(target,"reference"),reference));reference.textFromValueFunction=[](double v){return String(400+80*v,2)+" Hz";};reference.valueFromTextFunction=[](const String&v){return (v.getDoubleValue()-400)/80;};reference.updateText();referenceLabel.setText("A4 REFERENCE",dontSendNotification);
 reset.onClick=[this]{p.resetTuning(target);};store.setClickingTogglesState(true);store.onClick=[this]{storing=store.getToggleState();};for(int m=0;m<5;m++){auto&button=memories[(size_t)m];addAndMakeVisible(button);button.setButtonText(String(m+1));button.onClick=[this,m]{if(storing){p.storeTuning(target,m);store.setToggleState(false,dontSendNotification);storing=false;}else p.recallTuning(target,m);};}
 load.onClick=[this]{chooser=std::make_unique<FileChooser>("Load Scala scale",File::getSpecialLocation(File::userDocumentsDirectory),"*.scl");Component::SafePointer<TuningPanel>safe(this);chooser->launchAsync(FileBrowserComponent::openMode|FileBrowserComponent::canSelectFiles,[safe](const FileChooser&fc){if(!safe||fc.getResult()==File())return;String error;if(!safe->p.loadScala(safe->target,fc.getResult().loadFileAsString(),error))AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Scala import failed",error);});};
 help.setText("Click a note: toggle -50 ct. Drag/type offsets: +/-200 ct, repeated relative to ROOT.\nScala: one key per degree; MIDI 60 + ROOT anchors the scale. No .kbm import.\nSTORE then 1-5 saves; 1-5 recalls. Maqam settings are editable starting points.\nMASTER ON applies this scale to all layers. OFF restores individual layer scales.\nBYPASS disables this tuning scope. All settings are saved with the patch.",dontSendNotification);help.setFont(12);help.setMinimumHorizontalScale(1);refresh();
 }
 void refresh(){using namespace juce;info.setText(p.scaleDescription(target),dontSendNotification);root.setSelectedId(1+roundToInt(p.parameters.getRawParameterValue(p.tuningId(target,"root"))->load()*11),dontSendNotification);for(int n=0;n<12;n++)keys[(size_t)n].setToggleState(std::abs(p.parameters.getRawParameterValue(p.tuningId(target,"note"+String(n)))->load()-.5f)>.001f,dontSendNotification);}
 void resized()override{int w=getWidth();title.setBounds(8,4,w-330,30);master.setBounds(w-320,4,312,30);presets.setBounds(8,48,w/2-16,32);root.setBounds(w/2,48,130,32);bypass.setBounds(w/2+140,48,190,32);int cw=(w-16)/12;for(int n=0;n<12;n++){keys[(size_t)n].setBounds(8+n*cw,90,cw-4,34);cents[(size_t)n].setBounds(8+n*cw,132,cw-4,128);}referenceLabel.setBounds(8,276,120,28);reference.setBounds(126,276,w/2-134,28);scala.setBounds(w/2,276,126,28);load.setBounds(w/2+130,276,112,30);reset.setBounds(w-88,276,80,30);info.setBounds(8,314,w-16,28);store.setBounds(8,350,90,32);for(int m=0;m<5;m++)memories[(size_t)m].setBounds(110+m*58,350,50,32);help.setBounds(8,396,w-16,90);}
};
